insert into public.tips (id, unit_id, title_en, body_md, status) values
  ('f09f8f3b-acf3-5ae9-a200-3c92a0932524', '4090ef74-4ded-5132-9a43-cb791fd75c1f', 'Yo en tu lugar', '**Yo en tu lugar** — *in your shoes* — is *yo que vos* with a straighter face. The advice after it is still *would*: **yo en tu lugar, hablaría con él**, **yo me quedaría**.', 'draft'),
  ('72c29712-67a6-5044-b9df-f64344054e94', '4090ef74-4ded-5132-9a43-cb791fd75c1f', 'Asking back', 'Throw it back at your friend with the vos ending, **-ías**: **¿vos qué le dirías?** — *what would you tell him?* **Tendrías que** is advice with gloves on: **tendrías que llamarlo**, softer than *tenés que*.', 'draft'),
  ('c5227fd8-1b19-5d26-9531-0d6bc4e5fc58', '4090ef74-4ded-5132-9a43-cb791fd75c1f', 'Same short stems', '*Salir* shortens like *tener*: **saldría**, as *tendría*. The rest just add **-ía**: **volvería**, **pediría**, **dejaría**, **buscaría**.', 'draft'),
  ('4984f0a5-6d1b-5dac-958f-3d5f88e20b03', '22657b95-75bd-59a7-a1f7-c21e5df3a6a5', 'Any verb after si', 'The *if* form works for every verb: take the *ellos* past and swap **-ron** for **-ra**. *Ganaron* → **si ganara**, *vivieron* → **si viviera**. Then *would*: **viviría**, **daría**, **sabría**.', 'draft'),
  ('8ea5b476-7546-5c9b-95a8-649e4b351088', '22657b95-75bd-59a7-a1f7-c21e5df3a6a5', 'We and you', 'Dreaming together: **si tuviéramos plata, iríamos a Bariloche** — the *we* form carries an accent, **tuviéramos**. Asking a friend: **si pudieras, ¿dónde vivirías?** — *si pudieras* is the vos form.', 'draft'),
  ('3119b315-f5ed-5147-b49a-92275496d2ce', '7713400b-1007-558d-b717-ac7b02078eed', 'The polite would', 'The conditional takes the edge off a request: *¿me das una mano?* becomes **¿me darías una mano?**, *¿me ayudás?* becomes **¿me ayudarías?**. **¿Te molestaría…?** — *would you mind…?* — works like *me gustaría*.', 'draft'),
  ('a1ed21d8-6f6f-54a3-8bb5-3a6585fe6f0e', '7713400b-1007-558d-b717-ac7b02078eed', 'Suggest, and say no nicely', '**Podríamos ir al cine** — *we could go to the movies*. **Nos convendría salir temprano** — *we''d better leave early*. Turning it down: **preferiría ir otro día**. Saying yes: **con gusto**.', 'draft'),
  ('e12f1835-3c2a-51a4-8b5e-5fe9eac80c94', '54b42859-ce39-5f29-baa3-7a9aaff0d480', 'Would, for everyone', '**Hablaría**, **me quedaría** (I, he, she) · **¿qué dirías?** (vos) · **iríamos**, **podríamos** (we). Same *-ía* ending, a different last letter.', 'draft'),
  ('cc6f4c93-242d-540c-aaa7-7c4d554e7648', '54b42859-ce39-5f29-baa3-7a9aaff0d480', 'If we had', '**Si ganara**, **si viviera**, **si tuviéramos**: the *if* half takes *-ra*, the other half *-ía*. Politely, the *-ía* alone is enough: **¿te molestaría esperar?**', 'draft'),
  ('97e6c524-59bf-5483-b652-95a1e627cae7', 'ed66a36e-5a88-56f2-a2c7-3fdf72291b4e', 'Out of the city', 'Leaving Buenos Aires you take **la autopista**, then **la ruta**. First you **cargás nafta** — *nafta*, never *gasolina* — and on the way you pay the **peaje**. **La General Paz** is the ring road between the Capital and the conurbano.', 'draft'),
  ('e29e946c-4a6c-5287-bd02-bb2c355378aa', 'ed66a36e-5a88-56f2-a2c7-3fdf72291b4e', 'Manejé, ¿manejaste?', '*Manejar* in the past is regular: **manejé**, **¿manejaste vos?**. **Chocar** swaps *c* for *qu* before *é*: **choqué**. Run a red light and it''s **una multa**.', 'draft'),
  ('9cabde8c-14a1-59c5-afcc-463bd29cbf7f', 'ed66a36e-5a88-56f2-a2c7-3fdf72291b4e', 'Papers and parking', 'Your driving licence is the **registro** — *¿tenés registro?*. A paid parking space or garage is a **cochera**.', 'draft'),
  ('236b1e04-683a-52e4-a177-8cd11208527d', '97d7588e-37ef-5171-9640-6d51b0ac06ba', 'Te debo, me debés', '**Te debo mil pesos** — *I owe you*; **me debés la mitad** — *you owe me half*. Friends split the bill **a medias**, and a **deuda** between friends gets paid **a fin de mes**.', 'draft'),
  ('719de067-63a0-5d5b-9ad3-c29affadaa38', '97d7588e-37ef-5171-9640-6d51b0ac06ba', '¿Débito o crédito?', 'The question at every till. **Crédito** usually means **cuotas**, and the good ones are **sin interés**. Your savings sit in a **caja de ahorro**.', 'draft'),
  ('9a9f029d-8897-58a1-862d-3762db0207f1', '97d7588e-37ef-5171-9640-6d51b0ac06ba', '¿Te alcanza?', '*No me alcanza* for you is **¿te alcanza?** — *do you have enough?*. **Cobré** — *I got paid*; **¿gastás mucho?**, **¿ahorrás algo?** — vos adds **-ás**.', 'draft'),
  ('51b423d8-0511-58d0-8b45-1470af269ac1', '4093ca08-4709-5a01-b09b-4fd1624d96cf', 'Dice, me contaron', 'One source: **mi vieja dice que…**. Several: **me contaron que…**, **me comentaron que…** — *people told me*. Porteño news travels by word of mouth and by **audio**.', 'draft'),
  ('f448808c-e949-5196-9800-8ef7088251d6', '4093ca08-4709-5a01-b09b-4fd1624d96cf', '¿Es cierto?', 'Before you pass it on: **¿es cierto?** — *is it true?* — or **es mentira** — *it''s a lie*. **Lo leyó en las redes** — *she read it on social media* — is not a source.', 'draft'),
  ('375791dd-270a-541e-90ed-5b241e5fb3d0', '4093ca08-4709-5a01-b09b-4fd1624d96cf', '¿Escuchaste?', '**¿Escuchaste la radio?** — the vos past, like *leíste*. And a tip from someone who knows is **un dato**: *me pasaron el dato*.', 'draft'),
  ('d5a41816-9c68-5afc-a6e5-786e6e3e162d', '949c47b5-e244-52bc-9153-03f632f3e5b8', 'Past, for you and me', '**Manejé**, **cargué**, **choqué**, **cobré** — *I*. **¿Manejaste?**, **¿escuchaste?** — *you*. **Leyó**, **comentó** — *he, she*. **Contaron** — *they*.', 'draft'),
  ('9346219b-01db-5b68-9ade-830d9f45c8b8', '949c47b5-e244-52bc-9153-03f632f3e5b8', 'Money between friends', '**Me debés la mitad**, **pagamos a medias**, **¿te alcanza?**. And news between friends: **me contaron que…**, **¿es cierto?**', 'draft'),
  ('411110dd-943a-5910-bf5f-9a7c66ad7eef', 'a56af3ac-cade-5ff7-bdce-38285c0c74e8', 'Medio, re', 'Porteños grade a person with two little words: **re** turns it up — *es re generosa* — and **medio** turns it down — *es medio vago*, *he''s a bit lazy*. **Medio** never changes: *medio tonta*, *medio serios*.', 'draft'),
  ('3cf567c2-f4d8-5988-b290-df55a3a1ea54', 'a56af3ac-cade-5ff7-bdce-38285c0c74e8', 'The good and the bad', '**Macanudo** is the old-school *great guy*; **trabajador** is *hard-working*. **Agrandado** is *full of himself*, **egoísta** *selfish* — and *egoísta* is the same for him and for her, like *inteligente*.', 'draft'),
  ('501983de-04c6-5c67-bc94-ddd15cb1a88c', 'a56af3ac-cade-5ff7-bdce-38285c0c74e8', 'Plural', 'Describe a group with **son** and an **-s**: **son re trabajadores**, **son medio distraídos**. A mixed group takes the *-os* form.', 'draft'),
  ('ca47c7e9-05d9-5bfa-9df1-7a8c4223003a', '4e77d43e-13ea-5b40-9c1e-dafbe4fd7210', 'Quedan, te queda', 'Two places: **quedan** — *Recoleta y Belgrano quedan en zona norte*. For you: **¿te queda cerca?** — *is it close for you?*. It''s the same *queda*, with whoever it''s for in front.', 'draft'),
  ('ef2f7720-75af-506a-a7fb-1581bde273b9', '4e77d43e-13ea-5b40-9c1e-dafbe4fd7210', 'Norte y sur', '**Zona norte** — Recoleta, Belgrano, and the suburbs past the General Paz — has the money and the **árboles**; **zona sur** — La Boca, and the conurbano to the south — is cheaper. Caballito, Almagro and Villa Crespo sit in the middle.', 'draft'),
  ('cb6dfb5e-e16a-521b-acd9-c1457f587cd8', '4e77d43e-13ea-5b40-9c1e-dafbe4fd7210', 'Al lado de', '**Al lado de** — *next to*: **Almagro queda al lado de Caballito**. Before *el* it shrinks: **al lado del parque**.', 'draft'),
  ('ac8034cf-361d-549f-8562-a1bbd6af1043', 'ce25b1d0-ee42-5039-a068-263c69e918ce', '¿Qué le preguntaste?', 'Now the vos side: **¿qué le preguntaste?**, **¿qué le contestaste?** — the same *-aste* as *llamaste*. And for him or her: **me explicó que…**, **me juró que…**, **me gritó**.', 'draft'),
  ('c2f43780-ee3d-53bd-a45e-b6d1ddc3d20d', 'ce25b1d0-ee42-5039-a068-263c69e918ce', 'Venías, podías', 'Reported, *venís* becomes **venías** and *podés* becomes **podías**: *«¿Venís?»* → **me preguntó si venías**; *«No puedo»* → **me dijo que no podía**.', 'draft'),
  ('8470eb4b-a03c-53fb-8cb4-2718b4e1b17c', 'ce25b1d0-ee42-5039-a068-263c69e918ce', 'Te juro', '**Te juro** — *I swear* — is how a porteño vouches for the story: **te juro que me dijo eso**. A long talk with a friend is **una charla**: **charlé con Sofi**.', 'draft'),
  ('8c3c3de9-43f2-5d5d-9b9f-e3f6f455056f', 'b2645ccd-6674-5c14-b607-432b9778545a', 'What people are like, and where places are', 'People: **es medio vago**, **son re trabajadores**. Places: **quedan en zona norte**, **¿te queda cerca?**', 'draft'),
  ('8c55bf88-92a8-53fe-87ab-041bf1b86674', 'b2645ccd-6674-5c14-b607-432b9778545a', 'Tell it on', '**¿Qué le preguntaste?** — **le pregunté si venías**. What was said steps back a tense: *podés* → **podías**, *venís* → **venías**.', 'draft'),
  ('6adce778-5bd3-5ead-8fc5-69d118ef84f7', 'ad8fbd77-4b75-55d5-9322-1d952fd8511c', 'Fillers', 'A porteño sentence breathes through its fillers: **ponele** — *let''s say*; **digamos** — *sort of*; **qué sé yo** — *I dunno*; **bah** — *well, I mean*: *son las ocho, bah, ponele*.', 'draft'),
  ('c6b40c9b-6758-5732-b6d5-1a559be96347', 'ad8fbd77-4b75-55d5-9322-1d952fd8511c', 'Yes, no, and no way', '**¡Más vale!** — *of course!*; **sí o sí** — *no matter what*; **ni loco** — *no way*. And when there''s too much going on: **estoy a full** — *I''m flat out*.', 'draft')
